package mailer

import("crypto/tls";"fmt";"html";"net";"net/smtp";"strings";"time")
type Mailer struct{Host,Port,Username,Password,From string}
func(m Mailer)Enabled()bool{return m.Host!=""&&m.Port!=""&&m.From!=""}
func(m Mailer)SendReset(to,link string)error{if !m.Enabled(){return fmt.Errorf("smtp is not configured")};addr:=net.JoinHostPort(m.Host,m.Port);conn,err:=net.DialTimeout("tcp",addr,5*time.Second);if err!=nil{return err};defer conn.Close();_=conn.SetDeadline(time.Now().Add(12*time.Second));client,err:=smtp.NewClient(conn,m.Host);if err!=nil{return err};defer client.Close();if ok,_:=client.Extension("STARTTLS");ok{if err:=client.StartTLS(&tls.Config{ServerName:m.Host,MinVersion:tls.VersionTLS12});err!=nil{return err}};if m.Username!=""{if err:=client.Auth(smtp.PlainAuth("",m.Username,m.Password,m.Host));err!=nil{return err}};if err:=client.Mail(m.From);err!=nil{return err};if err:=client.Rcpt(to);err!=nil{return err};w,err:=client.Data();if err!=nil{return err};message:=strings.Join([]string{"From: "+m.From,"To: "+to,"Subject: Reset your Coolgards password","MIME-Version: 1.0","Content-Type: text/html; charset=UTF-8","","<p>We received a request to reset your Coolgards password.</p>",`<p><a href="`+html.EscapeString(link)+`">Reset password</a></p>`,"<p>If you did not request this, you can ignore this email. The link expires in 30 minutes.</p>"},"\r\n");if _,err:=w.Write([]byte(message));err!=nil{_=w.Close();return err};if err:=w.Close();err!=nil{return err};return client.Quit()}
